package com.forgeflow.jobservice.service;
import com.fasterxml.jackson.databind.*; import com.forgeflow.jobservice.api.JobDtos.*; import com.forgeflow.jobservice.model.*; import com.forgeflow.jobservice.repo.*; import org.springframework.data.domain.PageRequest; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.Instant; import java.util.*;
@Service public class JobApplicationService {
 private final JobRepository jobs; private final JobAttemptRepository attempts; private final OutboxEventRepository outbox; private final WorkerHeartbeatRepository workers; private final ObjectMapper mapper;
 public JobApplicationService(JobRepository jobs,JobAttemptRepository attempts,OutboxEventRepository outbox,WorkerHeartbeatRepository workers,ObjectMapper mapper){this.jobs=jobs;this.attempts=attempts;this.outbox=outbox;this.workers=workers;this.mapper=mapper;}
 @Transactional public Job create(CreateJobRequest req,String owner){if(req.type()==null||!Set.of("GENERATE_REPORT","SIMULATE_FAILURE","FETCH_RSS_FEED").contains(req.type().toUpperCase(Locale.ROOT)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Supported job types: GENERATE_REPORT, SIMULATE_FAILURE, FETCH_RSS_FEED"); String type=req.type().toUpperCase(Locale.ROOT); String priority=req.priority()==null?"NORMAL":req.priority().toUpperCase(Locale.ROOT); if(!Set.of("LOW","NORMAL","HIGH").contains(priority))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Priority must be LOW, NORMAL or HIGH"); int max=req.maxAttempts()==null?3:req.maxAttempts(); if(max<1||max>10)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"maxAttempts must be between 1 and 10"); if(req.idempotencyKey()!=null&&!req.idempotencyKey().isBlank()){var old=jobs.findByOwnerIdAndIdempotencyKey(owner,req.idempotencyKey());if(old.isPresent())return old.get();}
  Instant now=Instant.now(); String mode=req.scheduleMode()==null?"NOW":req.scheduleMode().toUpperCase(Locale.ROOT); Instant runAt="LATER".equals(mode)&&req.runAt()!=null?req.runAt():now; if(runAt.isBefore(now))runAt=now; JobStatus status=runAt.isAfter(now)?JobStatus.SCHEDULED:JobStatus.QUEUED; String payload; try{payload=mapper.writeValueAsString(req.payload()==null?mapper.createObjectNode():req.payload());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid payload");}
  Job job=new Job(UUID.randomUUID().toString(),type,priority,status,owner,blankToNull(req.idempotencyKey()),payload,max,runAt); jobs.save(job); if(status==JobStatus.QUEUED)outbox.save(new OutboxEvent(job.getId(),"JOB_QUEUED")); return job; }
 private String blankToNull(String x){return x==null||x.isBlank()?null:x;}
 @Transactional(readOnly=true) public List<Job> list(String owner,boolean all){return all?jobs.findTop200ByOrderByCreatedAtDesc():jobs.findTop200ByOwnerIdOrderByCreatedAtDesc(owner);}
 @Transactional(readOnly=true) public Job get(String id,String owner,boolean all){Job job=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found")); if(!all&&!job.getOwnerId().equals(owner))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found");return job;}
 @Transactional(readOnly=true) public List<JobAttempt> attempts(String id,String owner){get(id,owner,false);return attempts.findByJobIdOrderByAttemptNumberAsc(id);}
 @Transactional public Job cancel(String id,String owner){Job j=get(id,owner,false);if(Set.of(JobStatus.SCHEDULED,JobStatus.QUEUED,JobStatus.RETRY_WAIT).contains(j.getStatus())){j.setStatus(JobStatus.CANCELLED);return jobs.save(j);}throw new ResponseStatusException(HttpStatus.CONFLICT,"Only queued, scheduled or retry-wait jobs can be cancelled");}
 @Transactional public Job manualRetry(String id){Job j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found"));if(j.getStatus()!=JobStatus.DEAD)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only dead jobs can be manually retried");j.setMaxAttempts(j.getAttempts()+j.getMaxAttempts());j.setLastError(null);j.setCompletedAt(null);j.setRunAt(Instant.now());j.setStatus(JobStatus.QUEUED);jobs.save(j);outbox.save(new OutboxEvent(j.getId(),"JOB_MANUAL_RETRY"));return j;}
 @Transactional public ClaimResponse claim(String id,String worker){Instant now=Instant.now();int changed=jobs.claim(id,worker,now.plusSeconds(45),now,JobStatus.RUNNING,JobStatus.QUEUED);if(changed==0)return new ClaimResponse(false,null);Job j=jobs.findById(id).orElseThrow();return new ClaimResponse(true,new ExecutionJob(j.getId(),j.getType(),j.getPayloadJson(),j.getAttempts(),j.getMaxAttempts(),j.getPriority()));}
 @Transactional public void complete(String id,String worker,JsonNode result){Job j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found"));if(j.getStatus()!=JobStatus.RUNNING||!Objects.equals(worker,j.getLockedBy()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Worker does not own this running job");Instant now=Instant.now();attempts.save(new JobAttempt(id,j.getAttempts(),worker,"SUCCEEDED",j.getStartedAt(),now,null));try{j.setResultJson(mapper.writeValueAsString(result==null?mapper.createObjectNode():result));}catch(Exception ex){throw new IllegalStateException(ex);}j.setStatus(JobStatus.SUCCEEDED);j.setCompletedAt(now);j.setLastError(null);j.setLockedBy(null);j.setLeaseExpiresAt(null);}
 @Transactional public void fail(String id,String worker,String error){Job j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found"));if(j.getStatus()!=JobStatus.RUNNING||!Objects.equals(worker,j.getLockedBy()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Worker does not own this running job");Instant now=Instant.now();attempts.save(new JobAttempt(id,j.getAttempts(),worker,"FAILED",j.getStartedAt(),now,error));j.setLastError(shorten(error));j.setLockedBy(null);j.setLeaseExpiresAt(null);if(j.getAttempts()>=j.getMaxAttempts()){j.setStatus(JobStatus.DEAD);j.setCompletedAt(now);}else{j.setStatus(JobStatus.RETRY_WAIT);j.setRunAt(now.plusSeconds(retryDelaySeconds(j.getAttempts())));}}
 public long retryDelaySeconds(int attempt){return Math.min(60L,2L << Math.max(0,attempt-1));} private String shorten(String error){if(error==null)return "Unknown execution error";return error.length()>1800?error.substring(0,1800):error;}
 @Transactional public int dispatchDueAndRecover(){Instant now=Instant.now();int changed=0;for(Job j:jobs.findByStatusAndLeaseExpiresAtBefore(JobStatus.RUNNING,now)){String worker=j.getLockedBy();attempts.save(new JobAttempt(j.getId(),j.getAttempts(),worker,"FAILED",j.getStartedAt(),now,"Worker lease expired before completion"));j.setLastError("Worker lease expired before completion");j.setLockedBy(null);j.setLeaseExpiresAt(null);if(j.getAttempts()>=j.getMaxAttempts()){j.setStatus(JobStatus.DEAD);j.setCompletedAt(now);}else{j.setStatus(JobStatus.RETRY_WAIT);j.setRunAt(now.plusSeconds(retryDelaySeconds(j.getAttempts())));}changed++;}
  for(Job j:jobs.findByStatusInAndRunAtLessThanEqualOrderByRunAtAsc(List.of(JobStatus.SCHEDULED,JobStatus.RETRY_WAIT),now,PageRequest.of(0,100))){j.setStatus(JobStatus.QUEUED);outbox.save(new OutboxEvent(j.getId(),"JOB_DUE"));changed++;}return changed;}
 @Transactional public void heartbeat(String id,int active){workers.save(new WorkerHeartbeat(id,Math.max(0,active),Instant.now()));}
 @Transactional(readOnly=true) public List<WorkerHeartbeat> workerList(){return workers.findAll();}
 @Transactional(readOnly=true) public Map<String,Object> summary(String owner,boolean all){Map<String,Object> m=new LinkedHashMap<>();long total=all?jobs.count():jobs.countByOwnerIdAndStatus(owner,JobStatus.QUEUED)+jobs.countByOwnerIdAndStatus(owner,JobStatus.RUNNING)+jobs.countByOwnerIdAndStatus(owner,JobStatus.SCHEDULED)+jobs.countByOwnerIdAndStatus(owner,JobStatus.RETRY_WAIT)+jobs.countByOwnerIdAndStatus(owner,JobStatus.SUCCEEDED)+jobs.countByOwnerIdAndStatus(owner,JobStatus.DEAD)+jobs.countByOwnerIdAndStatus(owner,JobStatus.CANCELLED);m.put("total",total);for(JobStatus s:JobStatus.values())m.put(s.name().toLowerCase(Locale.ROOT),all?jobs.countByStatus(s):jobs.countByOwnerIdAndStatus(owner,s));m.put("generatedAt",Instant.now());return m;}
}
